    let hash = 2166136261 >>> 0;
    const ignored = new Set([
        gridEntity, pvPowerEntity,
        ...BATTERY_POWER_ENTITIES,
        'input_text.hpvc_accuracy_diagnostics_json',
        'input_text.hpvc_last_action',
        'input_text.hpvc_last_targets_json',
        'input_text.hpvc_reason',
        'input_text.hpvc_status'
