    const snapshot = {};
    for (const entity of BATTERY_POWER_ENTITIES) {
        const item = cycleStates[entity];
        const raw = item ? String(item.state ?? '').trim() : '__missing__';
        const numeric = Number(raw);
        snapshot[entity] = Number.isFinite(numeric)
