set -eu
node - <<'NODE'
const fs = require('fs');
const http = require('http');

const flowLabels = ["HPVC Engine v1.5.4", "HPVC Outputs v1.5.4", "HPVC Reports v1.5.4"];
const accessFile = '/tmp/hpvc-uninstall-nodered-access.json';
const manualFile = '/tmp/hpvc-uninstall-nodered-manual';

function request({host, port, method, path, headers = {}, body = null, timeout = 5000}) {
  return new Promise((resolve, reject) => {
    const req = http.request({host, port, method, path, headers}, res => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => resolve({status: res.statusCode || 0, body: data}));
    });
    req.on('error', reject);
    req.setTimeout(timeout, () => req.destroy(new Error('timeout')));
    if (body !== null) req.write(body);
    req.end();
  });
}

async function directAccess() {
  const envPorts = [process.env.PORT, process.env.NODE_RED_PORT, process.env.NODERED_PORT]
    .map(v => Number(v)).filter(Number.isFinite);
  const ports = [...new Set([...envPorts, 1880, 46836])];
  const errors = [];

  for (const port of ports) {
    const authHeaders = [
      {Accept: 'application/json'},
      ...(process.env.SUPERVISOR_TOKEN
        ? [{Accept: 'application/json', Authorization: `Bearer ${process.env.SUPERVISOR_TOKEN}`}]
        : [])
    ];

    for (const headers of authHeaders) {
      try {
        const r = await request({
          host: '127.0.0.1',
          port,
          method: 'GET',
          path: '/flows',
          headers
        });
        if (r.status >= 200 && r.status < 300) {
          return {
            mode: 'direct',
            port,
            headers,
            request: (method, path) => request({
              host: '127.0.0.1',
              port,
              method,
              path,
              headers
            })
          };
        }
        errors.push(`${port}: HTTP ${r.status}${headers.Authorization ? ' with add-on token' : ''}`);
      } catch (e) {
        errors.push(`${port}: ${e.message}${headers.Authorization ? ' with add-on token' : ''}`);
      }
    }
  }
  return {error: errors.join(', ')};
}

async function supervisor(method, path, body = null) {
  const token = String(process.env.SUPERVISOR_TOKEN || '');
  if (!token) throw new Error('SUPERVISOR_TOKEN unavailable');

  const payload = body === null ? null : JSON.stringify(body);
  const headers = {Authorization: `Bearer ${token}`, Accept: 'application/json'};
  if (payload !== null) {
    headers['Content-Type'] = 'application/json';
    headers['Content-Length'] = Buffer.byteLength(payload);
  }

  return request({
    host: 'supervisor',
    port: 80,
    method,
    path,
    headers,
    body: payload
  });
}

function supervisorData(r, label) {
  let obj;
  try { obj = JSON.parse(r.body || '{}'); }
  catch (_) { throw new Error(`${label}: invalid JSON`); }

  if (!(r.status >= 200 && r.status < 300) || obj.result === 'error') {
    throw new Error(`${label}: HTTP ${r.status} ${String(obj.message || r.body || '').slice(0,160)}`);
  }
  return obj.data || obj;
}

function extractIngressToken(entry) {
  const value = String(entry || '').trim();
  if (!value) return '';
  const m = value.match(/\/api\/hassio_ingress\/([^/?#]+)\/?/i);
  if (m) return m[1];
  const parts = value.split('/').filter(Boolean);
  return parts.length ? parts[parts.length - 1] : '';
}

async function ingressAccess() {
  let info = null;
  let lastError = null;

  for (const slug of ['self', 'a0d7b954_nodered']) {
    try {
      const r = await supervisor('GET', `/addons/${slug}/info`);
      info = supervisorData(r, `add-on info ${slug}`);
      if (info) break;
    } catch (e) {
      lastError = e;
    }
  }

  if (!info) throw lastError || new Error('Node-RED add-on info unavailable');

  const ingressToken = extractIngressToken(info.ingress_entry || info.ingress_url);
  if (!ingressToken) throw new Error('Node-RED ingress entry unavailable');

  const sr = await supervisor('POST', '/ingress/session', {});
  const sd = supervisorData(sr, 'ingress session');
  const session = String(sd.session || '');
  if (!session) throw new Error('Ingress session token missing');

  const token = String(process.env.SUPERVISOR_TOKEN || '');
  const ingressRequest = (method, path) => request({
    host: 'supervisor',
    port: 80,
    method,
    path: `/ingress/${encodeURIComponent(ingressToken)}/${String(path || '').replace(/^\/+/, '')}`,
    headers: {
      Accept: 'application/json',
      Cookie: `ingress_session=${session}`,
      Authorization: `Bearer ${token}`
    }
  });

  const probe = await ingressRequest('GET', '/flows');
  if (!(probe.status >= 200 && probe.status < 300)) {
    throw new Error(`Ingress Admin API probe failed: HTTP ${probe.status}`);
  }

  return {mode: 'ingress', ingressToken, session, request: ingressRequest};
}

async function removeAndVerify(access) {
  const before = await access.request('GET', '/flows');
  if (!(before.status >= 200 && before.status < 300)) {
    throw new Error(`Could not read Node-RED flows before deletion: HTTP ${before.status}`);
  }

  let flows;
  try { flows = JSON.parse(before.body); }
  catch (_) { throw new Error('Node-RED /flows returned invalid JSON'); }

  if (!Array.isArray(flows)) throw new Error('Node-RED /flows did not return an array');

  const idsByLabel = new Map(
    flows.filter(x => x && x.type === 'tab' && x.id && x.label)
         .map(x => [String(x.label), String(x.id)])
  );

  for (const label of flowLabels) {
    const id = idsByLabel.get(label);
    if (!id) continue; // already absent

    const r = await access.request('DELETE', '/flow/' + encodeURIComponent(id));
    if (![200, 204, 404].includes(r.status)) {
      throw new Error(`Failed deleting ${label} (${id}): HTTP ${r.status} ${String(r.body || '').slice(0,160)}`);
    }
  }

  const verify = await access.request('GET', '/flows');
  if (!(verify.status >= 200 && verify.status < 300)) {
    throw new Error(`Could not verify Node-RED flows after deletion: HTTP ${verify.status}`);
  }

  let after;
  try { after = JSON.parse(verify.body); }
  catch (_) { throw new Error('Node-RED /flows verification returned invalid JSON'); }

  const remainingLabels = new Set(
    (Array.isArray(after) ? after : [])
      .filter(x => x && x.type === 'tab' && x.label)
      .map(x => String(x.label))
  );

  const bad = flowLabels.filter(label => remainingLabels.has(label));
  if (bad.length) throw new Error('HPVC tabs still present after deletion: ' + bad.join(', '));
}

(async () => {
  try { fs.unlinkSync(accessFile); } catch (_) {}
  try { fs.unlinkSync(manualFile); } catch (_) {}

  let access = await directAccess();

  if (!access.request) {
    try {
      access = await ingressAccess();
    } catch (e) {
      fs.writeFileSync(
        manualFile,
        `Direct API unavailable (${access.error || 'unknown'}); Supervisor ingress unavailable (${e.message})\n`
      );
      process.stderr.write(
        'Automatic Node-RED removal unavailable; continue HPVC file/entity cleanup and remove the four HPVC tabs manually.\n'
      );
      process.exit(41);
    }
  }

  await removeAndVerify(access);

  const stored = access.mode === 'direct'
    ? {
        mode: 'direct',
        port: access.port,
        useSupervisorToken: Boolean(access.headers && access.headers.Authorization)
      }
    : {mode: 'ingress', ingressToken: access.ingressToken, session: access.session};

  fs.writeFileSync(accessFile, JSON.stringify(stored));
  fs.chmodSync(accessFile, 0o600);
  process.stdout.write(access.mode);
})().catch(err => {
  try { fs.unlinkSync(accessFile); } catch (_) {}
  try {
    fs.writeFileSync(manualFile, String(err.message || err) + '\n');
  } catch (_) {}
  process.stderr.write(
    'Automatic Node-RED cleanup could not complete (' + String(err.message || err) +
    '). HPVC will continue Home Assistant/file cleanup; remove any remaining HPVC Node-RED tabs manually.\n'
  );
  process.exit(41);
});
NODE

