const fs = require('fs');
const http = require('http');

const inputLabel = "HPVC Inputs v1.5.4";
const accessFile = '/tmp/hpvc-uninstall-nodered-access.json';
const failedFile = '/tmp/hpvc-uninstall-final.failed';

function wait(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function request({host, port, method, path, headers = {}, timeout = 5000}) {
  return new Promise((resolve, reject) => {
    const req = http.request({host, port, method, path, headers}, res => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => resolve({status: res.statusCode || 0, body: data}));
    });
    req.on('error', reject);
    req.setTimeout(timeout, () => req.destroy(new Error('timeout')));
    req.end();
  });
}

function buildRequester() {
  const access = JSON.parse(fs.readFileSync(accessFile, 'utf8'));

  if (access.mode === 'direct') {
    const port = Number(access.port);
    if (!Number.isFinite(port)) throw new Error('Stored direct port invalid');

    const headers = {Accept: 'application/json'};
    if (access.useSupervisorToken === true) {
      const token = String(process.env.SUPERVISOR_TOKEN || '');
      if (!token) throw new Error('SUPERVISOR_TOKEN unavailable to final direct cleanup');
      headers.Authorization = `Bearer ${token}`;
    }

    return (method, path) => request({
      host: '127.0.0.1',
      port,
      method,
      path,
      headers
    });
