const pending = global.get('homePvControlPendingWriteVerification');
const pendingWriteActive = Boolean(
    pending &&
    pending.checked !== true &&
    Array.isArray(pending.requested) &&
    pending.requested.length > 0 &&
    Number.isFinite(Number(pending.requested_ts)) &&
    (now - Number(pending.requested_ts)) < 120000
