const disableRestore = global.get('homePvControlDisableRestoreState');
const disableRestoreActive = usableInverterConfigured && Boolean(disableRestore && disableRestore.active === true);

const override = global.get('homePvControlNegativePriceHbcOverride');
const hbcOverrideActive = Boolean(override && typeof override === 'object');
const hbcOverridePhase = hbcOverrideActive ? String(override.phase || '') : '';
const hbcManualRecoveryRequired = hbcOverridePhase === 'recovery_unknown_previous';

const safeShutdownComplete =
    enabledOff &&
    postDisableEvaluationComplete &&
    !runtimeLockFresh &&
    !pendingWriteActive &&
    !disableRestoreActive &&
    !configuredInverterUnavailable &&
    !configuredInverterNotFull &&
    !hbcOverrideActive;

flow.set(
    'hpvc_uninstall_shutdown_poll_count',
    Number(flow.get('hpvc_uninstall_shutdown_poll_count') || 0) + 1
