if (safeShutdownComplete) {
    global.set('homePvControlUninstallShutdownActive', false);
    global.set('homePvControlUninstallShutdownCompletedAt', now);
    flow.set('hpvc_uninstall_shutdown_poll_started_at', 0);
    node.status({fill:'green',shape:'dot',text:'safe shutdown complete'});
    return [msg, null, null];
}

if (elapsed >= MAX_WAIT_MS) {
    global.set('homePvControlUninstallShutdownActive', false);
    msg.hpvcUninstallError =
        `Safe shutdown did not complete within ${Math.round(MAX_WAIT_MS / 1000)} s ` +
        `(status=${hpvcStatus || 'unknown'}, evaluation=${postDisableEvaluationComplete ? 'confirmed' : 'pending'}, ` +
        `runtime=${runtimeLockFresh ? 'busy' : 'idle'}, write=${pendingWriteActive ? 'pending' : 'idle'}, ` +
        `restore=${disableRestoreActive ? 'active' : 'idle'}, ` +
        `inverters=${configuredInverterUnavailable ? 'unavailable/unverifiable' : (configuredInverterNotFull ? 'not at full limit' : 'verified')}, ` +
        `hbc=${hbcManualRecoveryRequired ? 'manual recovery required' : (hbcOverrideActive ? 'restoring' : 'idle')}). ` +
        (configuredInverterUnavailable ? `Unverifiable inverter(s): ${inverterVerification.unavailable.join(', ')}. ` : '') +
        (configuredInverterNotFull ? `Inverter(s) not confirmed at full limit: ${inverterVerification.notFull.join(', ')}. ` : '') +
        'Cleanup was stopped before helper values were erased. Verify the listed inverter limits manually, restore connectivity/readback if needed, and retry uninstall.';
    node.status({fill:'red',shape:'ring',text:'safe shutdown timeout'});
    return [null, msg, null];
}

node.status({
    fill:'yellow',
    shape:'ring',
    text: !postDisableEvaluationComplete
        ? 'waiting for engine evaluation'
        : configuredInverterUnavailable
            ? `waiting for ${inverterVerification.unavailable.join(', ')}`
            : configuredInverterNotFull
                ? `verifying full limit: ${inverterVerification.notFull.join(', ')}`
                : disableRestoreActive
            ? 'restoring PV limits'
            : pendingWriteActive
            ? 'waiting for inverter write'
            : runtimeLockFresh
                ? 'waiting for runtime'
                : hbcManualRecoveryRequired
                    ? 'HBC manual recovery required'
                    : hbcOverrideActive
