// If the detached updater died abruptly it cannot publish a terminal HA status.
// A user retry is therefore allowed to launch a recovery probe without clearing
// the existing local latch or overwriting the saved resume intent. The detached
// updater's process lock is authoritative: a live owner refuses this probe with
// zero shared-state mutation; a dead owner can enter verified transaction recovery.
if(flow.get('hpvc_update_in_progress')===true){
    const helperOff=String(states['input_boolean.hpvc_update_in_progress']?.state||'off')!=='on';
    const updateStatus=String(states['input_text.hpvc_update_status']?.state||'');
    const terminal=/^(Update stopped|Update recovery requires attention|v?\d+\.\d+\.\d+ installed and verified)/i.test(updateStatus);
    if(helperOff&&terminal){
        flow.set('hpvc_update_in_progress',false);
        flow.set('hpvc_update_started_at',0);
        flow.set('hpvc_update_recovery_probe_at',0);
        flow.set('hpvc_update_phase','');
    }else{
        const phase=String(flow.get('hpvc_update_phase')||'');
        // A fresh ordinary update owns the latch while the safe-shutdown gate is
        // still restoring/confirming PV and HBC state. Repeated clicks must never
        // bypass that gate and reach an installer.
        if(phase==='shutdown'){
            node.status({fill:'yellow',shape:'ring',text:'waiting for safe update shutdown'});
