if(flow.get('hpvc_flow_removal_in_progress')===true){ node.status({fill:'yellow',shape:'ring',text:'manual upgrade already running'}); return null; }
const avail=states['input_boolean.hpvc_update_available'];
if(!avail || String(avail.state)!=='on'){ node.status({fill:'yellow',shape:'ring',text:'no update available'}); return null; }
const wasEnabled=Boolean(states['input_boolean.hpvc_enabled'] && String(states['input_boolean.hpvc_enabled'].state)==='on');
flow.set('hpvc_update_in_progress',true);
