const pendingWriteActive = Boolean(pending && pending.checked !== true && Array.isArray(pending.requested) && pending.requested.length > 0 && Number.isFinite(Number(pending.requested_ts)) && (now - Number(pending.requested_ts)) < 120000);
const disableRestore = global.get('homePvControlDisableRestoreState');
const disableRestoreActive = usableInverterConfigured && Boolean(disableRestore && disableRestore.active === true);
const override = global.get('homePvControlNegativePriceHbcOverride');
const hbcOverrideActive = Boolean(override && typeof override === 'object');

const complete = enabledOff && postDisableEvaluationComplete && !runtimeLockFresh && !pendingWriteActive && !disableRestoreActive && !configuredInverterUnavailable && !configuredInverterNotFull && !hbcOverrideActive;
flow.set('hpvc_update_shutdown_poll_count', Number(flow.get('hpvc_update_shutdown_poll_count') || 0) + 1);
if (complete) {
    global.set('homePvControlUninstallShutdownActive', false);
    global.set('homePvControlUninstallShutdownCompletedAt', now);
