}
if (elapsed >= MAX_WAIT_MS) {
    global.set('homePvControlUninstallShutdownActive', false);
    flow.set('hpvc_update_in_progress', false);
    flow.set('hpvc_update_phase','');
    msg.hpvcUpdateError =
        'Safe PV restoration could not be confirmed within 180 s. The update was cancelled before any HPVC files or flows were replaced. ' +
        (configuredInverterUnavailable ? `Unverifiable inverter(s): ${inverterVerification.unavailable.join(', ')}. ` : '') +
        (configuredInverterNotFull ? `Inverter(s) not confirmed at full limit: ${inverterVerification.notFull.join(', ')}. ` : '') +
        'Restore connectivity/readback and verify every configured inverter is at its full limit before retrying.';
    node.status({fill:'red',shape:'ring',text:'update shutdown timeout'});
