}
node.status({
    fill:'yellow', shape:'ring',
    text: !postDisableEvaluationComplete ? 'waiting for engine evaluation'
        : configuredInverterUnavailable ? `waiting for ${inverterVerification.unavailable.join(', ')}`
        : configuredInverterNotFull ? `verifying full limit: ${inverterVerification.notFull.join(', ')}`
        : disableRestoreActive ? 'restoring PV limits'
        : pendingWriteActive ? 'waiting for inverter write'
        : runtimeLockFresh ? 'waiting for runtime'
        : hbcOverrideActive ? 'restoring HBC override'
        : 'confirming disabled state'
});
return [null, null, msg];

