function pidAlive(pid){try{process.kill(Number(pid),0);return true;}catch(_){return false;}}
function updaterLockOwner(lockPath){
 try{
  const raw=fs.readFileSync(lockPath,'utf8');
  const owner=JSON.parse(raw);
  if(!owner||!owner.txid||!Number.isFinite(Number(owner.pid)))throw new Error('incomplete owner metadata');
  return {owner};
 }catch(e){return {owner:null,error:e};}
}
function publishInitializedOwner(lockPath,txid,kind){
 const initPath=`${lockPath}.init-${txid}`;
 let fd=null;
 try{
  fd=fs.openSync(initPath,'wx',0o600);
  fs.writeFileSync(fd,JSON.stringify({txid,pid:process.pid,startedAt:Date.now(),kind}));
