 }
}
function acquireRecoveryGuard(dir){
 updaterRecoveryGuardPath=path.join(dir,'updater.reclaim.lock');
 updaterRecoveryGuardTxId=`reclaim-${Date.now()}-${process.pid}-${Math.random().toString(16).slice(2)}`;
 try{publishInitializedOwner(updaterRecoveryGuardPath,updaterRecoveryGuardTxId,'stale-reclaim');return;}
 catch(e){
  if(e.code!=='EEXIST')throw e;
  const current=updaterLockOwner(updaterRecoveryGuardPath);
  if(!current.owner)throw new Error('HPVC Smart Update stale-lock recovery is already reserved with unreadable ownership; refusing concurrent recovery');
  if(pidAlive(current.owner.pid))throw new Error(`Another HPVC Smart Update stale-lock recovery is active (PID ${current.owner.pid})`);
