  // second reclaimer cannot prove that another process has not just replaced it.
  throw new Error(`A stale HPVC Smart Update recovery guard remains from PID ${current.owner.pid}; remove updater.reclaim.lock only after confirming no updater process is running`);
 }
}
function releaseRecoveryGuard(){
 if(!updaterRecoveryGuardPath||!updaterRecoveryGuardTxId)return;
 try{const current=updaterLockOwner(updaterRecoveryGuardPath);if(current.owner&&String(current.owner.txid)===String(updaterRecoveryGuardTxId))fs.unlinkSync(updaterRecoveryGuardPath);}catch(_){}
 updaterRecoveryGuardPath='';updaterRecoveryGuardTxId='';
}
function quarantineStaleUpdaterLock(lockPath,expectedTxid,dir){
 acquireRecoveryGuard(dir);
 try{
  // Re-read only after exclusive stale-recovery ownership is established. While
  // the guard exists every other acquirer refuses publication/reclamation.
  const check=updaterLockOwner(lockPath);
  if(!check.owner||String(check.owner.txid)!==String(expectedTxid))throw new Error('HPVC Smart Update lock ownership changed before stale-lock recovery');
  if(pidAlive(check.owner.pid))throw new Error(`Another HPVC Smart Update process is still active (PID ${check.owner.pid})`);
  fs.unlinkSync(lockPath);
 }catch(e){releaseRecoveryGuard();throw e;}
}
function acquireUpdaterLock(base){
 const dir=path.join(base,'hpvc-data','update-recovery');fs.mkdirSync(dir,{recursive:true,mode:0o700});fs.chmodSync(dir,0o700);
 updaterLockPath=path.join(dir,'updater.lock');updaterTxId=`${Date.now()}-${process.pid}-${Math.random().toString(16).slice(2)}`;
 for(let attempt=0;attempt<3;attempt++){
  // A stale-recovery owner gets an exclusive publication window. A normal
  // contender must never publish a replacement while that window is active.
  if(!updaterRecoveryGuardTxId&&fs.existsSync(path.join(dir,'updater.reclaim.lock'))){
   const recovery=updaterLockOwner(path.join(dir,'updater.reclaim.lock'));
   if(!recovery.owner)throw new Error('HPVC Smart Update stale-lock recovery ownership is unreadable; refusing concurrent update');
   throw new Error(`HPVC Smart Update stale-lock recovery is reserved by PID ${recovery.owner.pid}`);
  }
  try{
   publishInitializedOwner(updaterLockPath,updaterTxId,'updater');
   releaseRecoveryGuard();
   return;
  }catch(e){
   if(e.code!=='EEXIST'){releaseRecoveryGuard();throw e;}
   const current=updaterLockOwner(updaterLockPath);
   if(!current.owner){releaseRecoveryGuard();throw new Error('HPVC Smart Update lock exists but ownership metadata is unreadable; refusing to reclaim uncertain ownership');}
   if(pidAlive(current.owner.pid)){releaseRecoveryGuard();throw new Error(`Another HPVC Smart Update process is still active (PID ${current.owner.pid})`);}
   if(attempt<2){
    quarantineStaleUpdaterLock(updaterLockPath,current.owner.txid,dir);
    continue;
   }
   releaseRecoveryGuard();
   throw new Error('HPVC Smart Update lock could not be acquired');
  }
 }
}
function releaseUpdaterLock(){
 releaseRecoveryGuard();
 if(!updaterLockPath||!updaterTxId)return;
 try{const current=updaterLockOwner(updaterLockPath);if(current.owner&&String(current.owner.txid)===String(updaterTxId))fs.unlinkSync(updaterLockPath);}catch(_){}
}
function wait(ms){return new Promise(r=>setTimeout(r,ms));}
function request(mod,opts,body=null){return new Promise((resolve,reject)=>{const req=mod.request(opts,res=>{let data='';res.on('data',c=>data+=c);res.on('end',()=>resolve({status:res.statusCode||0,body:data,headers:res.headers}));});req.on('error',reject);req.setTimeout(opts.timeout||15000,()=>req.destroy(new Error('timeout')));if(body!==null)req.write(body);req.end();});}
