async function resolveTagCommit(tag){let body=await httpsText(API_HOST,`/repos/${REPO}/git/ref/tags/${encodeURIComponent(tag)}`);let ref=JSON.parse(body);let obj=ref&&ref.object?ref.object:null;for(let depth=0;depth<5;depth++){if(!obj||!obj.sha||!obj.type)throw new Error('GitHub release tag could not be resolved');if(obj.type==='commit')return String(obj.sha);if(obj.type!=='tag')throw new Error(`GitHub release tag resolved to unsupported object type: ${obj.type}`);body=await httpsText(API_HOST,`/repos/${REPO}/git/tags/${encodeURIComponent(String(obj.sha))}`);const tagObj=JSON.parse(body);obj=tagObj&&tagObj.object?tagObj.object:null;}throw new Error('GitHub release tag resolution exceeded safe depth');}
async function latestRelease(){const body=await httpsText(API_HOST,`/repos/${REPO}/releases/latest`);const r=JSON.parse(body);const tag=String(r.tag_name||'').trim();if(!/^v?\d+\.\d+\.\d+(?:[-+].*)?$/.test(tag))throw new Error('Latest GitHub release tag is invalid');const commit=await resolveTagCommit(tag);if(!/^[0-9a-f]{40}$/i.test(commit))throw new Error('Resolved GitHub release commit is invalid');return {tag,commit,url:String(r.html_url||'')};}
function baseDir(){if(fs.existsSync('/homeassistant')&&fs.statSync('/homeassistant').isDirectory())return '/homeassistant';if(fs.existsSync('/homeassistant_config')&&fs.statSync('/homeassistant_config').isDirectory())return '/homeassistant_config';throw new Error('No Home Assistant config mount found');}
