function cleanVersion(value){return String(value||'').trim().replace(/^v/i,'').split(/[+-]/)[0];}
let yamlParser=null;
function strictYamlParser(){
 if(yamlParser)return yamlParser;
 const roots=[process.cwd(),'/config/node-red','/config','/data','/usr/src/node-red'];
 let YAML=null,lastError=null;
 for(const root of roots){
