}
function parseYamlStrict(buf,label){const value=strictYamlParser()(buf.toString('utf8'),label);if(!value||typeof value!=='object'||Array.isArray(value))throw new Error(`${label} must contain a YAML mapping at the document root`);return value;}
function findObjectByUniqueId(value,uniqueId){
 if(Array.isArray(value)){for(const v of value){const found=findObjectByUniqueId(v,uniqueId);if(found)return found;}return null;}
 if(value&&typeof value==='object'){if(String(value.unique_id||'')===uniqueId)return value;for(const v of Object.values(value)){const found=findObjectByUniqueId(v,uniqueId);if(found)return found;}}
