        effects,
        values: {
            pvDelta,
            rawPvDelta,
            postTriggerObservedPvDelta,
            postTriggerCommandedLimitDelta,
            postTriggerControllerPvComponent,
            postTriggerCommandTs: postTriggerCommands.length > 0 ? Number(postTriggerCommands[postTriggerCommands.length - 1].ts) : null,
            postTriggerCommandCount: postTriggerCommands.length,
            postTriggerCommandTimestamps: postTriggerCommands.map(item => Number(item.ts)),
            batteryDelta: batteryTriggerPairReliable ? triggerBatteryDelta : null,
            triggerBatteryDelta: batteryTriggerPairReliable ? triggerBatteryDelta : null,
            postTriggerBatteryDelta: postTriggerBatteryPairReliable ? postTriggerBatteryDelta : null,
            houseLoadDelta: houseLoadPairReliable ? houseLoadDelta : null,
            batteryReliable: batteryTriggerPairReliable,
            pvFreshAfterTrigger,
            batteryFreshAfterTrigger,
            houseLoadCoherent: houseLoadPairReliable,
            houseInferenceBlockReason,
            fullBoundaryBatteryEvidenceUsed,
            independentBatteryClassifiedOther,
            classificationNotes: classificationNotes.slice(),
            limitDelta,
            observedCommandedLimitDelta,
            uncommandedObservedLimitDelta,
            controllerPvComponent,
            externalLimitPvComponent,
            pvAvailabilityComponent,
            unexplainedGridResidual
        },
        signalTs: current.signalTs,
        commandTs: commandPredatesTrigger ? commandTs : null,
        commandAction: commandPredatesTrigger ? String(lastCommand.action || '') : '',
        commandVerification: commandPredatesTrigger ? String(lastCommand.verification || '') : '',
        continuityGeneration: detectorContinuityGeneration,
        usedForHeadline: false,
        usedAt: null,
        headlineUseCount: 0,
        lastHeadlineMatchTs: null,
        sustainedUntilTs: Number(pending.triggerTs) + PHYSICAL_EVENT_SUSTAIN_MAX_MS,
        physicalAfter: {
            grid: Number(current.grid || 0),
            pv: Number(current.pv || 0),
            batteryReliable: current.batteryReliable === true,
            batteryPower: Number.isFinite(Number(current.batteryPower)) ? Number(current.batteryPower) : null,
            houseLoad: Number.isFinite(Number(current.houseLoad)) ? Number(current.houseLoad) : null,
            limit: Number(current.limit || 0)
        }
    };

    // The grid may already have recovered while this trigger was waiting for sensor
    // reconciliation. Resolve the finalized event immediately in that case so it can
    // never be attached to a later unrelated excursion on the same action-band side.
    const recoveredBeforeFinalize = eventExcursionSide > 0
        ? Number(current.grid) <= importRecalc
        : Number(current.grid) >= exportStart;
    event.resolved = recoveredBeforeFinalize;
    event.resolvedAt = recoveredBeforeFinalize ? now : null;

    const previewWeights = normalizePhysicalWeights(effects, eventExcursionSide);
    const deferredHeadlineBurden = Math.max(0, Number(pending.headlineBurden || 0));
    if (deferredHeadlineBurden > 0 && previewWeights) {
        // Triggering headline samples are temporarily placed in Other while sensor
        // updates reconcile. Move that exact burden to the finalized physical weights.
        dailyAccuracy.headlineFactorSqZDt.other = Math.max(0,
            Number(dailyAccuracy.headlineFactorSqZDt.other || 0) - deferredHeadlineBurden);
        for (const key of ['control','load','pv','other']) {
            const share = Number(previewWeights[key] || 0);
            if (share <= 0) continue;
            dailyAccuracy.headlineFactorSqZDt[key] =
                Number(dailyAccuracy.headlineFactorSqZDt[key] || 0) + deferredHeadlineBurden * share;
        }
        event.usedForHeadline = false;
        event.usedAt = now;
        event.headlineUseCount = Number(event.headlineUseCount || 0) + 1;
        event.lastHeadlineMatchTs = now;
    }

    physicalEvents.push(event);
    physicalEvents = physicalEvents.slice(-PHYSICAL_EVENT_MAX_EVENTS);
    pushAttributionDiagnostic({
        phase: 'reconciled',
        eventId,
        eventAgeMs: Math.max(0, now - Number(pending.triggerTs)),
        reconcileMs: Math.max(0, now - Number(pending.triggerTs)),
        excursionSide: eventExcursionSide,
        gridDelta,
        triggerGridDelta: Number(pending.triggerGridDelta || 0),
        effects: { ...effects },
        weights: previewWeights,
        pvDelta,
        batteryDelta: batteryTriggerPairReliable ? triggerBatteryDelta : null,
        triggerBatteryDelta: batteryTriggerPairReliable ? triggerBatteryDelta : null,
        postTriggerBatteryDelta: postTriggerBatteryPairReliable ? postTriggerBatteryDelta : null,
        houseLoadDelta: houseLoadPairReliable ? houseLoadDelta : null,
        batteryReliable: batteryTriggerPairReliable,
        pvFreshAfterTrigger,
        batteryFreshAfterTrigger,
        houseLoadCoherent: houseLoadPairReliable,
        houseInferenceBlockReason,
        fullBoundaryBatteryEvidenceUsed,
        independentBatteryClassifiedOther,
        classificationNotes: classificationNotes.slice(),
        postTriggerControllerPvComponent,
        limitDelta,
        observedCommandedLimitDelta,
        uncommandedObservedLimitDelta,
        controllerPvComponent,
        externalLimitPvComponent,
        pvAvailabilityComponent,
        unexplainedGridResidual,
        deferredHeadlineBurden,
        commandTs: commandPredatesTrigger ? commandTs : null,
        commandAction: commandPredatesTrigger ? String(lastCommand.action || '') : '',
        commandVerification: commandPredatesTrigger ? String(lastCommand.verification || '') : ''
    });
    return event;
}

// Night Restore is outside the active PV-control attribution domain. Reset the
// detector across that boundary instead of creating expected stale-PV/battery blockers
// that would pollute daytime diagnostics or bridge night into the next morning.
if (detectorCoreInputsValid && !persistentNightRestore) {
    const detectorCurrent = detectorSnapshot();
    // A remembered event is usable only while the grid remains on the same action-band
    // side created by that event. Once grid returns inside the action band, the physical
    // event has been resolved and must not be attached to a later unrelated excursion.
    for (const event of physicalEvents) {
        if (!event || event.resolved === true) continue;
        const side = Number(event.excursionSide || 0);
        if (side > 0 && detectorCurrent.grid <= importRecalc) {
            event.resolved = true; event.resolvedAt = now;
        } else if (side < 0 && detectorCurrent.grid >= exportStart) {
            event.resolved = true; event.resolvedAt = now;
        }
    }

    // Finalize a pending trigger as soon as one normal evaluation has elapsed AND
    // PV has produced a genuinely fresh post-trigger observation. If OpenDTU is late,
    // keep the event open up to the adaptive 20-30 s deadline. This preserves event
    // throughput on healthy telemetry while still preventing false Other attribution.
    const pendingAgeMs = pendingPhysicalEvent && Number.isFinite(Number(pendingPhysicalEvent.triggerTs))
        ? Math.max(0, now - Number(pendingPhysicalEvent.triggerTs)) : 0;
    const pendingPvEvidenceReady = pendingPhysicalEvent &&
        pendingAgeMs >= Math.max(5000, Math.min(15000, NOMINAL_EVALUATION_MS)) &&
        Number.isFinite(Number(detectorCurrent.freshTs?.pv)) &&
        Number(detectorCurrent.freshTs.pv) >= Number(pendingPhysicalEvent.triggerTs);
    if (pendingPhysicalEvent && (pendingPvEvidenceReady || now >= Number(pendingPhysicalEvent.finalizeAt || 0))) {
        finalizePendingPhysicalEvent(pendingPhysicalEvent, detectorCurrent);
        pendingPhysicalEvent = null;
        global.set('homePvControlPendingPhysicalEvent', null);
    }

    const detectorPrevious = global.get('homePvControlPhysicalDetectorSample');
    if (detectorPrevious && Number.isFinite(Number(detectorPrevious.ts))) {
        const detectorDt = now - Number(detectorPrevious.ts);
        if (detectorDt > 0 && detectorDt <= PHYSICAL_EVENT_MAX_GAP_MS) {
            const detectorThreshold = Math.max(Number(deadband || 0), 25);
            const gridDelta = detectorCurrent.grid - Number(detectorPrevious.grid || 0);
            if (Math.abs(gridDelta) >= detectorThreshold && !pendingPhysicalEvent) {
                const eventExcursionSide = detectorCurrent.grid > importRecalc ? 1 : (detectorCurrent.grid < exportStart ? -1 : 0);
                if (eventExcursionSide !== 0) {
                    pendingPhysicalEvent = {
                        triggerTs: now,
                        finalizeAt: now + PHYSICAL_EVENT_RECONCILE_MS,
                        triggerGridDelta: gridDelta,
                        excursionSide: eventExcursionSide,
                        baseline: detectorPrevious,
                        trigger: detectorCurrent,
                        commandAtTrigger: Object.assign({}, global.get('homePvControlLastPvCommand') || {}),
                        headlineBurden: 0,
                        continuityGeneration: detectorContinuityGeneration
                    };
                    global.set('homePvControlPendingPhysicalEvent', pendingPhysicalEvent);
                    pushAttributionDiagnostic({
                        phase: 'pending',
                        eventAgeMs: 0,
                        excursionSide: eventExcursionSide,
                        gridDelta,
                        reconcileMs: PHYSICAL_EVENT_RECONCILE_MS,
                        batteryReliable: detectorCurrent.batteryReliable === true
                    });
                }
            }
        }
    }
    global.set('homePvControlPhysicalDetectorSample', detectorCurrent);
} else {
    // Never bridge invalid core detector input intervals. Battery telemetry is not a
    // core continuity requirement: when it is uncertain we continue PV/Control detection
    // in degraded mode and route battery-dependent residual to Other instead of inventing
    // House load. Grid/PV/inverter failures still invalidate the causal chain completely.
    global.set('homePvControlPhysicalDetectorSample', null);
    global.set('homePvControlPendingPhysicalEvent', null);
    global.set('homePvControlLastExternalLimitChange', null);
    global.set('homePvControlPvResponseAuthority', null);
    global.set('homePvControlPvResponseAuthorityRaw', null);
    global.set('homePvControlExternalPvResponseAuthority', null);
    global.set('homePvControlExternalPvResponseAuthorityRaw', null);
    lastExternalLimitChange = null;
    pendingPhysicalEvent = null;
    physicalEvents = [];
    detectorContinuityGeneration += 1;
    global.set('homePvControlPhysicalDetectorGeneration', detectorContinuityGeneration);
}
global.set('homePvControlPhysicalDetectorGeneration', detectorContinuityGeneration);
global.set('homePvControlRecentPhysicalEvents', physicalEvents);
global.set('homePvControlPendingPhysicalEvent', pendingPhysicalEvent);

function consumeRecentPhysicalEventWeights(harmfulDirection) {
    if (!Number.isFinite(Number(harmfulDirection)) || Number(harmfulDirection) === 0) return null;
    let events = Array.isArray(global.get('homePvControlRecentPhysicalEvents'))
        ? global.get('homePvControlRecentPhysicalEvents')
        : [];
    const nominalRepeatGap = Math.max(3000, Math.min(60000, NOMINAL_EVALUATION_MS * 1.75));
    events = events
        .filter(event => {
            if (!event || !Number.isFinite(Number(event.ts))) return false;
            const age = now - Number(event.ts);
            const recentlyRevalidated = Number.isFinite(Number(event.lastHeadlineMatchTs)) &&
                now - Number(event.lastHeadlineMatchTs) <= nominalRepeatGap;
            return age <= PHYSICAL_EVENT_MEMORY_MS ||
                (Number(event.headlineUseCount || 0) > 0 && recentlyRevalidated && age <= PHYSICAL_EVENT_SUSTAIN_MAX_MS);
        })
        .slice(-PHYSICAL_EVENT_MAX_EVENTS);

    const latestPhysical = global.get('homePvControlPhysicalDetectorSample') || null;
    function sustainedWeightsStillConsistent(event, weights) {
        // First use keeps the full finalized event mix. Reuse is stricter: each
        // known cause is revalidated independently, stale causes are masked out, and
        // the remaining active causes are renormalized. Pure Other stays one-shot.
        if (Number(event.headlineUseCount || 0) <= 0) return { ...weights };
        if (!latestPhysical || !event.physicalAfter) return null;

        const after = event.physicalAfter || {};
        const values = event.values || {};
        const active = { control: false, load: false, pv: false };

        if (Number(weights.load || 0) > 0.05 && Number.isFinite(Number(after.houseLoad)) &&
            latestPhysical.batteryReliable === true && Number.isFinite(Number(latestPhysical.houseLoad))) {
            const delta = Math.abs(Number(values.houseLoadDelta || 0));
            const tolerance = Math.max(100, deadband * 2, delta * 0.35);
            active.load = Math.abs(Number(latestPhysical.houseLoad) - Number(after.houseLoad)) <= tolerance;
        }
        if (Number(weights.pv || 0) > 0.05 && Number.isFinite(Number(after.pv)) && Number.isFinite(Number(latestPhysical.pv))) {
            const delta = Math.abs(Number(values.pvAvailabilityComponent || values.pvDelta || 0));
            const tolerance = Math.max(100, deadband * 2, delta * 0.40);
            active.pv = Math.abs(Number(latestPhysical.pv) - Number(after.pv)) <= tolerance;
        }
        if (Number(weights.control || 0) > 0.05 && Number.isFinite(Number(after.limit)) && Number.isFinite(Number(latestPhysical.limit))) {
            const delta = Math.abs(Number(values.observedCommandedLimitDelta || values.limitDelta || 0));
            const tolerance = Math.max(50, deadband, delta * 0.25);
            const latestCommand = global.get('homePvControlLastPvCommand') || {};
            const eventCommandTs = Number(event.commandTs);
            const latestCommandTs = Number(latestCommand.ts);
            const sameOriginatingCommand = Number.isFinite(eventCommandTs) && Number.isFinite(latestCommandTs) &&
                latestCommandTs === eventCommandTs;
            const originatingCommandStillApplied = sameOriginatingCommand && commandCurrentlyApplied(latestCommand);
            // A newer unrelated HPVC command must never keep an older Control event alive.
            // The old event may still remain valid when the inverter limit itself stays
            // physically consistent with that event's post-command state.
            active.control = originatingCommandStillApplied ||
                Math.abs(Number(latestPhysical.limit) - Number(after.limit)) <= tolerance;
        }

        let activeTotal = 0;
        const masked = { control: 0, load: 0, pv: 0, other: 0 };
        for (const key of ['control','load','pv']) {
            if (active[key]) {
                masked[key] = Math.max(0, Number(weights[key] || 0));
                activeTotal += masked[key];
            }
        }
        if (activeTotal <= 1e-9) return null;
        for (const key of ['control','load','pv']) masked[key] /= activeTotal;
        return masked;
    }

    // Match the newest still-active event that created the same action-band excursion.
    // A sustained cause may contribute to several time-weighted headline samples, but
    // only while the physical state remains consistent and continuously revalidated.
    for (let index = events.length - 1; index >= 0; index--) {
        const event = events[index];
        if (event.resolved === true) continue;
        if (Number(event.continuityGeneration || 0) !== Number(detectorContinuityGeneration)) continue;
        if (Number(event.excursionSide || 0) !== Number(harmfulDirection)) continue;
        if (Number(harmfulDirection) * Number(event.gridDelta || 0) <= 0) continue;
        const gridBefore = Number(event.gridBefore);
        const gridAfter = Number(event.gridAfter);
        if (!Number.isFinite(gridBefore) || !Number.isFinite(gridAfter)) continue;
        const eventAfterExcursion = Math.max(0, Number(harmfulDirection) * (gridAfter - exportTarget));
        const currentExcursion = Math.max(0, Number(harmfulDirection) * (grid - exportTarget));
        const retainedFraction = eventAfterExcursion > 0 ? currentExcursion / eventAfterExcursion : 0;
        if (retainedFraction < 0.25) continue;
        const baseWeights = normalizePhysicalWeights(event.effects || {}, harmfulDirection);
        if (!baseWeights) continue;
        const weights = sustainedWeightsStillConsistent(event, baseWeights);
        if (!weights) continue;

        event.usedForHeadline = false; // retained only for backward-compatible diagnostics
        event.usedAt = now;
        event.headlineUseCount = Number(event.headlineUseCount || 0) + 1;
        event.lastHeadlineMatchTs = now;
        global.set('homePvControlRecentPhysicalEvents', events);
        pushAttributionDiagnostic({
            phase: Number(event.headlineUseCount || 0) > 1 ? 'headline-sustained' : 'headline-consumed',
            eventId: String(event.id || ''),
            eventAgeMs: Math.max(0, now - Number(event.ts || now)),
            headlineUseCount: Number(event.headlineUseCount || 0),
            excursionSide: Number(event.excursionSide || 0),
            gridDelta: Number(event.gridDelta || 0),
            retainedFraction,
            effects: { ...(event.effects || {}) },
            baseWeights: { ...baseWeights },
            weights: { ...weights },
            values: { ...(event.values || {}) },
            commandTs: Number.isFinite(Number(event.commandTs)) ? Number(event.commandTs) : null,
            commandAction: String(event.commandAction || ''),
            commandVerification: String(event.commandVerification || '')
        });
        return weights;
    }
    global.set('homePvControlRecentPhysicalEvents', events);
    return null;
}

const accuracyBindingMargin = Math.max(deadband, 50);
// Score only when configured inverter limits appear physically binding. A limit
// below maximum does not curtail PV when available solar is below that limit.
const limitAppearsBindingForAccuracy =
    currentLimitTotalForAccuracy > 0 &&
    pvPower >= (currentLimitTotalForAccuracy - accuracyBindingMargin);
// A PV correction can start cooldown in the very same evaluation that observed the
// grid/load excursion which triggered that correction. Excluding that evaluation would
// throw away the pre-response measurement (for example an oven switching on) and make
// House load attribution impossible. Allow only the evaluation that *starts* cooldown;
// later cooldown evaluations remain excluded while the inverter/plant is settling.
const lastPvWriteMsForAccuracy = Number(flow.get('homePvControlLastPvWriteMs') || 0);
const cooldownStartedThisEvaluation =
    cooldownActiveNow === true &&
    lastPvWriteMsForAccuracy > 0 &&
    lastPvWriteMsForAccuracy === now;
const cooldownEligibleForAccuracy = !cooldownActiveNow || cooldownStartedThisEvaluation;

const targetAccuracyEligible =
    enabled &&
    stateIsNumeric(gridEntity) &&
    stateIsNumeric(pvPowerEntity) &&
    thresholdConfigurationValid &&
    pvLimitedForAccuracy &&
    limitAppearsBindingForAccuracy &&
    !wantsMinimumPv &&
    !persistentNightRestore &&
    // Charge Priority is excluded only while it is actually influencing PV control.
    hbcResponseWindowActive !== true &&
    hbcExportLimitingSuppressed !== true &&
    pvAction !== 'charge_priority_increase' &&
    cooldownEligibleForAccuracy &&
    !['Disabled', 'Waiting for inputs', 'Waiting for restore', 'Inputs unavailable', 'Configuration error'].includes(status);

if (!targetAccuracyEligible) {
    dailyAccuracy.lastEligibleSampleTs = null;
    dailyAccuracy.previousTargetSample = null;
} else {
    const previousEligibleTs = Number(dailyAccuracy.lastEligibleSampleTs);
    const gapOpener = !Number.isFinite(previousEligibleTs) || previousEligibleTs <= 0;
    const rawDt = gapOpener ? NOMINAL_EVALUATION_MS : Math.max(0, now - previousEligibleTs);
    const dt = gapOpener
        ? NOMINAL_EVALUATION_MS
        : (rawDt > 0 ? Math.min(rawDt, MAX_WEIGHT_MS) : NOMINAL_EVALUATION_MS);

    // Friendly 0-100 headline: side-aware, action-band-referenced NRMSE. Samples
    // inside Export Start...Import Restore have z=0 by policy. Beyond either trigger,
    // normalize the excursion by four times that side's target-to-trigger distance.
    let z = 0;
    if (grid < exportStart) {
        const sideScale = Math.max(Math.abs(exportTarget - exportStart), 1);
        z = (exportStart - grid) / (SCORE_SCALE_K * sideScale);
    } else if (grid > importRecalc) {
        const sideScale = Math.max(Math.abs(importRecalc - exportTarget), 1);
        z = (grid - importRecalc) / (SCORE_SCALE_K * sideScale);
    }

    // Physical engineering metrics are independent of Export Start/Import Restore.
    // They measure tracking to Target Export after allowing the configured deadband.
    const targetError = Math.abs(grid - exportTarget);
    const e = Math.max(0, targetError - deadband);
    const headlineHarmfulDirection = grid > importRecalc
        ? 1
        : (grid < exportStart ? -1 : Math.sign(grid - exportTarget));
    const detectorHeadlineWeights = z > 0
        ? consumeRecentPhysicalEventWeights(headlineHarmfulDirection)
        : null;
    const pendingHeadlineEvent = z > 0 ? (global.get('homePvControlPendingPhysicalEvent') || null) : null;
    const headlineAwaitingReconcile = !!(
        pendingHeadlineEvent &&
        Number(pendingHeadlineEvent.continuityGeneration || 0) === Number(detectorContinuityGeneration) &&
        Number(pendingHeadlineEvent.excursionSide || 0) === Number(headlineHarmfulDirection) &&
        Number.isFinite(Number(pendingHeadlineEvent.triggerTs)) &&
        now - Number(pendingHeadlineEvent.triggerTs) >= 0 &&
        now - Number(pendingHeadlineEvent.triggerTs) <= PHYSICAL_EVENT_MEMORY_MS
    );
    const headlineWeightsFromDetector = detectorHeadlineWeights !== null;

    dailyAccuracy.sumDt += dt;
    dailyAccuracy.sumSqZDt += z * z * dt;
    dailyAccuracy.sumSqEDt += e * e * dt;
    dailyAccuracy.sumEDt += e * dt;
    dailyAccuracy.targetCount += 1;
    if (z > 0) dailyAccuracy.bandExcursionCount += 1;
    if (e > 0) {
        dailyAccuracy.outsideDeadbandDt += dt;
        dailyAccuracy.outsideSumSqEDt += e * e * dt;
        dailyAccuracy.outsideSumEDt += e * dt;
    }

    // Headline-loss attribution is intentionally separate from target-tracking
    // attribution. Only z>0 samples can reduce Daily Control Accuracy. The causal
    // classifier below supplies a factor when possible; otherwise the actual
    // excursion is honestly retained as Other/unclassified.
    // Current-state controller evidence is safe to inspect even when this sample
    // opens a new eligibility chain. What is unsafe across a gap are *deltas* to a
    // previous PV/load sample. This distinction prevents real controller excursions
    // after a gap/restart from being forced into Other merely because continuity broke.
    const changeThreshold = Math.max(deadband, 25);
    const currentLimit = inverters.reduce((sum, inv) => sum + Number(inv.current || 0), 0);
    const lastPvWriteMs = Number(flow.get('homePvControlLastPvWriteMs') || 0);
    const writeAgeMs = lastPvWriteMs > 0 ? Math.max(0, now - lastPvWriteMs) : Infinity;
    const recentControllerWrite = writeAgeMs <= targetComparisonWindowMs;
    const settlingActive = pvPostWriteSettling === true;
    const atEffectiveMinimum = inverters.length > 0 && inverters.every(
        inv => inv.current <= (inv.minimum_power + deadband)
    );
    const atEffectiveMaximum = inverters.length > 0 && inverters.every(
        inv => inv.current >= (inv.full_power - deadband)
    );
    const currentControllerResponse =
        pvAction !== 'none' ||
        status === 'PV dynamically adjusted' ||
        status === 'PV restored';
    const latestCommandForEvidence = global.get('homePvControlLastPvCommand') || {};
    const latestCommandAgeForEvidence = Number.isFinite(Number(latestCommandForEvidence.ts))
        ? Math.max(0, now - Number(latestCommandForEvidence.ts))
        : Infinity;
    const appliedRecentControllerCommand =
        latestCommandAgeForEvidence <= targetComparisonWindowMs &&
        commandCurrentlyApplied(latestCommandForEvidence);
    // A requested action is not itself proof that HPVC caused the measured excursion.
    // Fallback Control attribution requires an applied/confirmed recent command or a
    // real observed control boundary. This prevents failed writes from becoming Control.
    const currentControllerEvidence =
        appliedRecentControllerCommand ||
        (settlingActive && appliedRecentControllerCommand) ||
        atEffectiveMinimum ||
        atEffectiveMaximum;

    let headlineWeights = headlineAwaitingReconcile
        ? { control: 0, load: 0, pv: 0, other: 1 }
        : (detectorHeadlineWeights || ((z > 0 && currentControllerEvidence)
            ? { control: 1, load: 0, pv: 0, other: 0 }
            : { control: 0, load: 0, pv: 0, other: 1 }));
    if (e > 0) {
        const errorBurden = e * dt;
        const previousSample = dailyAccuracy.previousTargetSample;

        if (gapOpener || !previousSample || !Number.isFinite(Number(previousSample.ts))) {
            // Raw target-tracking attribution cannot use PV/load deltas across an
            // eligibility gap or restart, so it remains diagnostically unattributed.
            // Headline attribution is different: if this sample itself is a real
            // action-band excursion and current controller state proves an active/
            // recent response, the current-state headline weights above can still honestly be Control.
            dailyAccuracy.unattributedErrorDt += errorBurden;
        } else {
            const elapsed = Math.max(0, now - Number(previousSample.ts));
            const previousLimit = Number(previousSample.limit);
            const limitChange = Number.isFinite(previousLimit) ? currentLimit - previousLimit : 0;
            const pvChange = pvPower - Number(previousSample.pv || 0);
            const batteryPower = physicalBatteryReliable ? Number(detectorBatteryPower) : NaN;
            const previousHouseLoad = Number(previousSample.houseLoad);
            // Grid import is positive and export negative. HBC battery power is signed
            // negative while charging, so PV + grid + battery power removes battery
            // charging/discharging from the residual and better isolates real house load.
            const currentHouseLoad = physicalBatteryReliable ? pvPower + grid + batteryPower : NaN;
            const houseLoadChange = physicalBatteryReliable && Number.isFinite(previousHouseLoad)
                ? currentHouseLoad - previousHouseLoad
                : 0;
            const gridChange = grid - Number(previousSample.grid || 0);
            const activeControllerResponse =
                currentControllerResponse ||
                Math.abs(limitChange) >= changeThreshold;
            const insideActionBand = grid >= exportStart && grid <= importRecalc;
            const controllerContext =
                !insideActionBand ||
                activeControllerResponse ||
                recentControllerWrite ||
                settlingActive ||
                atEffectiveMinimum ||
                atEffectiveMaximum;

            if (!controllerContext) {
                // Physical target error exists, but HPVC is deliberately configured
                // not to act here. Keep it in RMS/MAE, not in a causal factor bucket.
                dailyAccuracy.policyExcludedErrorDt += errorBurden;
            } else {
                // Residual-based, direction-aware causal model. First separate
                // measured PV movement into a controller-command component and a remaining
                // availability/weather component. Then project each physical component onto
                // the direction that made the current action-band excursion worse. Helpful
                // counter-movements are deliberately not charged as accuracy loss.
                const lastPvCommand = global.get('homePvControlLastPvCommand') || {};
                const commandAgeMs = Number.isFinite(Number(lastPvCommand.ts))
                    ? Math.max(0, now - Number(lastPvCommand.ts))
                    : Infinity;
                const currentPvSignalTs = stateTimestampMs(pvPowerEntity);
                const commandPrecedesObservedPv =
                    Number.isFinite(Number(lastPvCommand.ts)) &&
                    Number(lastPvCommand.ts) < (Number.isFinite(Number(currentPvSignalTs)) ? Number(currentPvSignalTs) : now);
                const observedCommandedLimitDelta = commandPathObservedDelta(lastPvCommand, previousLimit, currentLimit);
                const uncommandedObservedLimitDelta = limitChange - observedCommandedLimitDelta;
                if (Math.abs(uncommandedObservedLimitDelta) >= PHYSICAL_COMPONENT_NOISE_W) {
                    global.set('homePvControlPvResponseAuthorityRaw', null);
                    lastExternalLimitChange = { ts: now, delta: uncommandedObservedLimitDelta };
                    global.set('homePvControlLastExternalLimitChange', lastExternalLimitChange);
                    addExternalPvResponseAuthority(uncommandedObservedLimitDelta, 'raw');
                }

                // Raw target-tracking diagnostics use their own consumable HPVC
                // PV-response authority. One observed watt of HPVC limit motion can explain
