</style></head><body><main><header class="top"><div><h1>HPVC report</h1><div class="meta">${esc(report.generated)} · v${esc(report.version)}</div></div><button id="download">Download report</button></header>${runtimeWarning}<nav><a href="#summary">Status</a><a href="#live">Live</a><a href="#decision">Decision</a><a href="#accuracy">Accuracy</a><a href="#inverters">Inverters</a><a href="#settings">Settings</a><a href="#hbc">Batteries</a><a href="#health">Sensors</a>${performanceDiagnosticsHtml ? '<a href="#performance">Performance</a>' : ''}<a href="#insights">Insights</a><a href="#activity">Power control</a></nav>
<section id="summary"><h2>Executive Summary</h2><div class="panel">${row('HPVC status',s.enabled?'Enabled':'Disabled')}${row('External release request',s.externalReleaseRequested?'On':'Off')}${row('External release active',s.externalReleaseActive?'Yes':'No')}${row('Disable restore active',s.disableRestore?.active?'Yes':'No')}${row('Last disable restore',s.disableRestore?.last?`${s.disableRestore.last.result} at ${s.disableRestore.last.completedAt>0?new Date(s.disableRestore.last.completedAt).toISOString():'unavailable'}`:'No retained event')}${row('Last disable PV restore',s.disableRestore?.last?.pvRestoreRequested?(s.disableRestore.last.pvRestored?'Completed':'Not confirmed'):'Not required')}${row('Last disable HBC restore',s.disableRestore?.last?.hbcRestoreRequested?(s.disableRestore.last.hbcRestored?'Completed':'Not confirmed'):'Not required')}${row('Configuration',s.configValid?'Valid':'Invalid')}${row('Control mode',s.controlMode)}${row('Current decision',s.status)}${row('Reason',s.reason)}${row('Status since',s.currentAction)}${row('Action result',s.actionResult)}${row('HBC control',s.hbcControl?'On':'Off')}${row('HBC strategy',s.hbcStrategy)}${row('Runtime evaluation',s.runtimeEvaluationTime)}${s.runtimeDiagnosticsWarning?row('Runtime data warning',s.runtimeDiagnosticsWarning):''}</div></section>
<section id="live"><h2>Live Status</h2><div class="live-grid">${card('GRID',finite(report.live.grid)?`${Math.abs(Math.round(report.live.grid))} W ${report.live.grid<0?'export':'import'}`:'unavailable',`Target ${watts(settings.targetExport)}`)}${card('PV',watts(report.live.pv,1),'Current solar power')}${card('CHARGE PRIORITY',report.hbc.chargePriorityState || (report.hbc.chargePriorityActive?'Active':'Off'),report.hbc.increasePossible?'PV increase possible':report.hbc.stateReason)}${card('MARKET/EXPORT PRICE',price(report.live.market),'PV control price')}${card('ALL-IN PRICE',price(report.live.allIn),'Negative-price control')}</div></section>
<section id="decision"><h2>Decision Evaluation</h2><div class="panel">${row('Export limiting condition',d.exportTriggered?'Triggered':'Not triggered')}${row('Import restore condition',d.importTriggered?'Triggered':'Not triggered')}${row('PV currently limited',d.pvLimited?'Yes':'No')}${row('Negative-price mode',d.negativeMode?'Active':'Inactive')}${row('Cooldown',d.cooldown?'Active':'Inactive')}${row('Deadband',d.deadbandInside?'Inside':'Outside')}${row('Minimum PV block',d.minimumPvBlock?'Active':'Inactive')}${row('Grid error to target',watts(d.gridError))}${row('PV target baseline',d.pvTargetBaseline||'unavailable')}${row('Post-write PV settling',d.pvPostWriteSettling?'Active':'Inactive')}${row('Post-write settle age',age(d.pvPostWriteSettleAgeSeconds))}${row('HBC Charge Priority',d.chargePriorityState || (d.chargePriorityActive?'Active':'Off'))}${row('PV increase possible',report.hbc.increasePossible?'Yes':'No')}${row('Charge Priority reason',report.hbc.stateReason)}${row('Taper probe',d.taperProbeActive?'Active':'Inactive')}${row('Decision snapshot',d.runtimeEvaluationTime)}${row('Decision snapshot age',age(d.runtimeDiagnosticsAgeSeconds))}${d.runtimeDiagnosticsWarning?row('Decision data warning',d.runtimeDiagnosticsWarning):''}</div></section>
<section id="accuracy"><h2>Today’s Accuracy</h2><div class="accuracy-grid"><article class="card accuracy-card"><div class="accuracy-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><circle cx="12" cy="12" r="1.2"/><path d="M12 2v3M22 12h-3M12 22v-3M2 12h3"/></svg></div><div class="accuracy-title">Daily Control Accuracy</div><div class="accuracy-score${accuracyHasData?'':' no-data'}">${esc(accuracyValue)}</div><div class="accuracy-subtitle">Action-band compliance score while PV limits were physically binding · Charge Priority control influence excluded</div><div class="accuracy-groups"><div class="metric-heading">Score context</div><div class="metric-row"><span>Result confidence</span><strong>${esc(`${report.accuracy.confidence || 'Low'}${report.accuracy.confidenceReason ? ` — ${report.accuracy.confidenceReason}` : ''}`)}</strong></div><div class="metric-row"><span>Control band</span><strong>${esc(`${watts(settings.exportStart)} … ${watts(settings.importRestore)}`)}</strong></div><div class="metric-row"><span>Target/deadband</span><strong>${esc(`${watts(settings.targetExport)} ± ${watts(settings.deadband)}`)}</strong></div><div class="metric-row"><span>Band excursions</span><strong>${Math.max(0,Number(report.accuracy.bandExcursions||0))} / ${Math.max(0,Number(report.accuracy.samples||0))}</strong></div><div class="metric-heading">Target-tracking engineering metrics</div><div class="metric-row"><span>RMS control error</span><strong>${esc(watts(report.accuracy.rmsControlError,1))}</strong></div><div class="metric-row"><span>MAE control error</span><strong>${esc(watts(report.accuracy.maeControlError,1))}</strong></div><div class="metric-row"><span>Time outside target deadband</span><strong>${finite(report.accuracy.timeOutsideDeadbandPercent)?Number(report.accuracy.timeOutsideDeadbandPercent).toFixed(1)+'%':'unavailable'}</strong></div><div class="metric-row"><span>Deadband-exceedance RMS/MAE</span><strong>${finite(report.accuracy.deadbandExceedanceRatio)?Number(report.accuracy.deadbandExceedanceRatio).toFixed(2):'—'}</strong></div><div class="metric-heading">Estimated headline accuracy loss</div>${accuracyFactorsHtml}${accuracyCoverageHtml}${accuracyAttributionDiagnosticsHtml}</div><div class="accuracy-footer"><span>Daily control-band score</span><span class="rating-pill">${esc(report.accuracy.rating)}</span></div></article></div></section>
<section id="inverters"><h2>Inverters</h2><div class="grid2">${inverterCards}</div><div class="panel" style="margin-top:12px"><div class="report-subsection-title first">Inverter Diagnostics</div>${row('Configured inverters',inv.configuredCount)}${row('Available inverters',inv.availableCount)}${row('Unavailable inverters',Math.max(0,inv.configuredCount-inv.availableCount))}${row('Current total limit',watts(inv.currentTotal))}${row('Minimum total limit',watts(inv.minimumTotal))}${row('Maximum total power',watts(inv.maximumTotal))}${row('Calculated total target',watts(inv.targetTotal))}${row('Difference to target',watts(inv.targetTotal-inv.currentTotal))}${row('Available increase',watts(Math.max(0,inv.maximumTotal-inv.currentTotal)))}${row('Available reduction',watts(Math.max(0,inv.currentTotal-inv.minimumTotal)))}${row('Pending writes',inv.requestedCount)}${row('Write verification',inv.verificationStatus)}${row('Last write reason',inv.lastWriteReason)}${row('Last write time',inv.lastWriteTime)}${row('Last verification',inv.lastVerificationTime)}${row('Diagnostics timestamp',inv.diagnosticsTime)}${row('Diagnostics age',age(inv.diagnosticsAgeSeconds))}${row('Data source',inv.dataSource)}${row('Control mode',s.controlMode)}${report.adapterServiceError?row('Last adapter error',`${report.adapterServiceError.time} · ${String(report.adapterServiceError.controlKey).toUpperCase()} · ${report.adapterServiceError.phase} · ${report.adapterServiceError.action} · ${report.adapterServiceError.detail}`):''}</div></section>
<section id="settings"><h2>Control Settings</h2><div class="panel">${row('PV limit price',price(settings.limitPrice))}${row('Price hysteresis',price(settings.priceHysteresis))}${row('Force charge at negative price',settings.negativePriceHbcCharge?'On':'Off')}${row('Export Start',watts(settings.exportStart,1))}${row('Target Export',watts(settings.targetExport,1))}${row('Import Restore',watts(settings.importRestore,1))}${row('Minimum PV',watts(settings.minimumPv,1))}${row('Night restore PV',watts(settings.nightRestorePv,1))}${row('Cooldown',`${Number(settings.cooldownSeconds).toFixed(1)} s`)}${row('Deadband',watts(settings.deadband,1))}</div></section>
<section id="hbc"><h2>HBC & Battery Status</h2><div class="panel"><div class="report-subsection-title first">Current HBC State</div>${row('HBC status',report.hbc.available?'Detected':'Not detected')}${row('HBC control',report.hbc.control?'On':'Off')}${row('HBC Charge Priority',report.hbc.chargePriorityState || (report.hbc.chargePriorityActive?'Active':'Off'))}${row('HBC strategy',report.hbc.strategy)}${row('Executing substrategy',report.hbc.executing)}${row('HBC charge goal',report.hbc.chargeGoal)}${row('State reason',report.hbc.stateReason)}${row('PV increase possible',report.hbc.increasePossible?'Yes':'No')}<div class="report-subsection-title">Negative All-In Override</div>${row('Override state',report.hbc.negativeOverrideState)}${row('Minimum-PV lock',report.hbc.negativeOverrideLockActive?'Active':'Inactive')}${row('Override reason',report.hbc.negativeOverrideReason)}${row('Saved HBC strategy',report.hbc.negativeOverrideSavedStrategy||'—')}${row('Saved charge goal',report.hbc.negativeOverrideSavedChargeGoal||'—')}${row('Last override call',report.hbc.negativeOverrideLastCallStep||'—')}${row('Override phase age',age(report.hbc.negativeOverridePhaseAgeSeconds))}${row('Override retries',report.hbc.negativeOverrideRetryCount)}${row('Override fault',report.hbc.negativeOverrideFaultActive?'Active':'Inactive')}${row('Override persistence ready',report.hbc.negativeOverridePersistenceReady?'Yes':'No')}${row('Inverter minimum drift',report.hbc.negativeOverrideState==='inactive'?'Not applicable':(report.hbc.negativeOverrideInverterDrift.length?report.hbc.negativeOverrideInverterDrift.join(', '):'None'))}<div class="report-subsection-title">Charge Priority Capacity</div>${row('Eligible batteries',`${report.hbc.eligibleBatteryCount} (${report.hbc.below90EligibleCount} normal, ${report.hbc.taperEligibleCount} taper-aware)`)}${row('Usable batteries',report.hbc.usableCount)}${row('Uncertain batteries excluded',report.hbc.uncertainExcluded)}${row('Unavailable batteries excluded',report.hbc.unavailableExcluded)}${row('RS485-disabled batteries excluded',report.hbc.controlDisabledExcluded||0)}${row('Combined battery headroom',watts(report.hbc.combinedBatteryHeadroom))}${row('Normal battery headroom',watts(report.hbc.normalBatteryHeadroom))}${row('Controlled taper allowance',watts(report.hbc.taperBatteryAllowance))}${row('Existing grid export',watts(report.hbc.existingGridExport))}${row('Net absorbable headroom',watts(report.hbc.netAbsorbableHeadroom))}${row('Remaining inverter capacity',watts(report.hbc.remainingInverterCapacity))}${row('Charge Priority step cap',watts(report.hbc.stepCap))}${row('Calculated PV increase',watts(report.hbc.calculatedIncrease))}${row('Charge Priority target',watts(report.hbc.targetTotal))}${row('Taper probe',report.hbc.taperProbeActive?'Active':'Inactive')}<div class="report-subsection-title">Batteries</div><div class="grid2">${batteryCards}</div><div class="report-subsection-title">HBC & Battery Diagnostics</div>${row('Charge Priority diagnostics',report.hbc.diagnosticsEvaluationTime)}${row('Charge Priority internal state',report.hbc.stateMachineState||'off')}${row('HBC prioritized battery',report.hbc.prioritizedBattery?`M${report.hbc.prioritizedBattery}`:'—')}${row('HBC battery order',Array.isArray(report.hbc.batteryOrder)&&report.hbc.batteryOrder.length?report.hbc.batteryOrder.map(i=>`M${i}`).join(' → '):'—')}${row('HBC priority cycle',report.hbc.priorityCycleMode||'Unknown')}${row('HBC priority configuration',report.hbc.priorityConfigurationValid?'Valid':`Invalid${report.hbc.priorityConfigurationReason?` — ${report.hbc.priorityConfigurationReason}`:''}`)}${row('Confirmed-charge enter threshold',watts(report.hbc.confirmedChargeEnterThreshold))}${row('Confirmed-charge remain threshold',watts(report.hbc.confirmedChargeRemainThreshold))}${row('Measured battery charge power',watts(report.hbc.batteryChargePower))}${row('Battery charging confirmed',report.hbc.batteryChargingConfirmed?'Yes':'No')}${row('HBC response window',report.hbc.responseWindowActive?'Active':'Inactive')}${row('HBC response window duration',finite(report.hbc.responseWindowMs)?`${Math.round(report.hbc.responseWindowMs/1000)} s`:'unavailable')}${row('HBC response window remaining',finite(report.hbc.responseWindowRemainingMs)?`${Math.ceil(report.hbc.responseWindowRemainingMs/1000)} s`:'unavailable')}${row('Charge Priority exit hold',report.hbc.exitHoldActive?'Active':'Inactive')}${row('Charge Priority exit hold duration',finite(report.hbc.exitHoldMs)?`${Math.round(report.hbc.exitHoldMs/1000)} s`:'unavailable')}${row('Charge Priority exit hold remaining',finite(report.hbc.exitHoldRemainingMs)?`${Math.ceil(report.hbc.exitHoldRemainingMs/1000)} s`:'unavailable')}${row('Persistent export age',finite(report.hbc.persistentExportAgeMs)?`${Math.round(report.hbc.persistentExportAgeMs/1000)} s`:'unavailable')}${row('Export fallback threshold',finite(report.hbc.exportFallbackMs)?`${Math.round(report.hbc.exportFallbackMs/1000)} s`:'unavailable')}${row('Export fallback',report.hbc.exportFallbackActive?'Active':'Inactive')}${row('HPVC export limiting suppressed',report.hbc.exportLimitingSuppressed?'Yes':'No')}${row('Battery diagnostics timestamp',report.hbc.diagnosticsTime)}${row('Battery diagnostics age',age(report.hbc.diagnosticsAgeSeconds))}</div></section>
<section id="health"><h2>Sensor Health</h2><div class="panel">${healthRows}</div></section>
${performanceDiagnosticsHtml ? `<section id="performance"><h2>Performance Diagnostics</h2>${performanceDiagnosticsHtml}</section>` : ``}
<section id="insights"><h2>Today’s Insights</h2><div class="panel insight-source-note">${row('Insight history source',report.insightHistorySource || 'latest-10 fallback')}</div><details class="compact"><summary><span>Today’s insights · ${esc(insightSummary.total || 0)} events · ${esc(insightSummary.grouped || 0)} consecutive entries</span><span class="summary-badges"><svg class="badge-dot critical" viewBox="0 0 12 12" role="img" aria-hidden="true"><circle cx="6" cy="6" r="5"/></svg> ${esc(insightSummary.critical || 0)} critical · <svg class="badge-dot warning" viewBox="0 0 12 12" role="img" aria-hidden="true"><circle cx="6" cy="6" r="5"/></svg> ${esc(insightSummary.warnings || 0)} warnings · <svg class="badge-dot info" viewBox="0 0 12 12" role="img" aria-hidden="true"><circle cx="6" cy="6" r="5"/></svg> ${esc(insightSummary.information || 0)} info</span></summary><div class="details-body"><div class="insight-list">${insightRows}</div></div></details></section>
<section id="activity"><h2>Power Control — PV-limiting price zone</h2><p class="activity-note">Only activity from entry into the Market/export-price PV-limiting zone until exit above the configured restore threshold is shown. Activity outside that price window is intentionally omitted.</p>${activitySummaryHtml}${activityMetricsHtml}<details class="compact activity-table"><summary><span>Activity log · ${esc(act.rowCount || 0)} rows</span><span class="summary-badges">Show details</span></summary><div class="details-body"><div class="table-wrap"><table><thead><tr><th>Time</th><th>Mode</th><th>Grid</th><th>PV</th><th>Battery</th><th>Limit</th><th>Event</th></tr></thead><tbody>${activityRows}</tbody></table></div></div></details><p class="activity-note">Constrained-capacity and battery-energy values are estimates from sparse active-control intervals. Restore energy is intentionally not estimated because stepped restores cannot be reconstructed reliably from activity events.</p></section><div class="floating-actions" aria-label="Report navigation"><button id="collapse-floating" class="floating-button hidden" type="button" aria-label="Collapse expanded Insights and Power Control sections">▲ Collapse</button><button id="top-floating" class="floating-button hidden" type="button" aria-label="Return to top of report">↑ Top</button></div><pre id="raw" class="hidden">${esc(msg.hpvcTxtReport)}</pre></main><script>(async()=>{try{const current=document.querySelector('meta[name="hpvc-generated"]')?.content||'';const response=await fetch(location.pathname+'?fresh='+Date.now(),{cache:'no-store',headers:{'Cache-Control':'no-cache'}});if(response.ok){const fresh=await response.text();const match=fresh.match(/<meta name="hpvc-generated" content="([^"]+)"/);if(match&&match[1]&&match[1]!==current){document.open();document.write(fresh);document.close();return;}}}catch(_){}})();document.getElementById('download').onclick=()=>{const b=new Blob([document.getElementById('raw').textContent],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='hpvc-report-${esc(report.generatedIso.replace(/[:.]/g,'-'))}.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};const expandableSections=[...document.querySelectorAll('details.compact')];const collapseButton=document.getElementById('collapse-floating');const topButton=document.getElementById('top-floating');function currentScrollTop(){return Math.max(window.scrollY||0,document.documentElement?.scrollTop||0,document.body?.scrollTop||0,document.scrollingElement?.scrollTop||0)}function updateFloatingButtons(){const hasOpenSection=expandableSections.some(section=>section.open);collapseButton?.classList.toggle('hidden',!hasOpenSection);topButton?.classList.toggle('hidden',currentScrollTop()<400)}function syncFloatingButtons(){requestAnimationFrame(()=>requestAnimationFrame(updateFloatingButtons))}expandableSections.forEach(section=>section.addEventListener('toggle',updateFloatingButtons));window.addEventListener('scroll',updateFloatingButtons,{passive:true});window.addEventListener('load',syncFloatingButtons,{once:true});window.addEventListener('pageshow',syncFloatingButtons);window.addEventListener('resize',syncFloatingButtons,{passive:true});window.addEventListener('orientationchange',syncFloatingButtons,{passive:true});document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncFloatingButtons()});window.visualViewport?.addEventListener('resize',syncFloatingButtons,{passive:true});window.visualViewport?.addEventListener('scroll',syncFloatingButtons,{passive:true});setTimeout(updateFloatingButtons,100);setTimeout(updateFloatingButtons,500);setTimeout(updateFloatingButtons,1200);let __navUntil=performance.now()+3000;function __watchNav(){updateFloatingButtons();if(performance.now()<__navUntil)requestAnimationFrame(__watchNav)}requestAnimationFrame(__watchNav);collapseButton?.addEventListener('click',()=>{const firstOpen=expandableSections.find(section=>section.open);expandableSections.forEach(section=>{section.open=false});firstOpen?.scrollIntoView({behavior:'smooth',block:'start'});updateFloatingButtons()});topButton?.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));updateFloatingButtons();fetch('/api/webhook/hpvc_report_viewed_141',{method:'POST',keepalive:true}).catch(()=>{});</script></body></html>`;
msg.hpvcHtmlParityManifest = JSON.stringify(report.parityManifest || {});
msg.hpvcHtmlReport = msg.payload;
delete msg.hpvcHtmlParts;
return msg;

// Use a generation-specific temporary file so a timed-out report can never
// overwrite the temporary file of a newer generation.
const generationId = String(msg.hpvcReportGenerationId || '');
const activeId = String(flow.get('hpvcReportGenerationId') || '');
const cancelledId = String(flow.get('hpvcReportCancelledGenerationId') || '');
if (!generationId || generationId !== activeId || generationId === cancelledId) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'stale generation discarded' });
    return null;
}
if (!/^[0-9]+-[0-9a-f]+$/i.test(generationId)) throw new Error('Invalid HPVC report generation ID');
msg.hpvcReportTempPath = `/tmp/hpvc-report-root/support-report.${generationId}.tmp.html`;
msg.filename = msg.hpvcReportTempPath;
return msg;

// Re-check the generation after the file write. The 45-second watchdog may
// have cancelled this generation while filesystem I/O was in progress.
const generationId = String(msg.hpvcReportGenerationId || '');
const activeId = String(flow.get('hpvcReportGenerationId') || '');
