//   4) at least one normal engine evaluation completed after uninstall shutdown began;
//   5) the normal disable-restore lifecycle is finished;
//   6) any HPVC-owned HBC override has been released.
//
// The normal HPVC runtime itself decides whether PV needs restoring and keeps
// homePvControlDisableRestoreState active until the configured inverter limits are
// back at full (or there is no usable live restore path, e.g. sleeping/offline PV).
// Each retry also drives a fresh normal HPVC evaluation through output 3.

const now = Date.now();
const startedAt = Number(global.get('homePvControlUninstallShutdownStartedAt') || 0);
const elapsed = startedAt > 0 ? Math.max(0, now - startedAt) : 0;
const MAX_WAIT_MS = 180000;

const states = global.get('homeassistant.homeAssistant.states') || {};
