};

const enabledOff = stateOf('input_boolean.hpvc_enabled', 'on').toLowerCase() === 'off';
const hpvcStatus = stateOf('input_text.hpvc_status', '').trim();
const lastEvaluationAt = Number(global.get('homePvControlUninstallShutdownLastEvaluationAt') || 0);
const postDisableEvaluationComplete = startedAt > 0 && lastEvaluationAt >= startedAt;

function configuredInverterVerification(states, stateOf) {
    const rawCount = Number(stateOf('input_number.hpvc_inverter_count', '0'));
    const count = Number.isInteger(rawCount) ? Math.max(0, Math.min(10, rawCount)) : 0;
    const deadbandW = Math.max(1, Number(stateOf('input_number.hpvc_pv_adjust_deadband', '25')) || 25);
