    const notFull = [];
    let configuredCount = 0;

    const validEntityId = entity => typeof entity === 'string' && /^[a-z0-9_]+\.[a-z0-9_]+$/.test(entity.trim().toLowerCase());
    const numericState = entity => {
        if (!validEntityId(entity)) return null;
        const item = states[entity];
        if (!item || item.state === undefined || item.state === null) return null;
        const raw = String(item.state).trim().toLowerCase();
        if (!raw || ['unknown', 'unavailable', 'none'].includes(raw)) return null;
        const value = Number(raw);
        return Number.isFinite(value) ? value : null;
    };

    for (let slot = 1; slot <= count; slot++) {
        const method = stateOf(`input_select.hpvc_pv${slot}_control_method`, 'Number entity').trim();
        const limitEntity = stateOf(`input_text.hpvc_pv${slot}_limit_number`, '').trim().toLowerCase();
        const action = stateOf(`input_text.hpvc_pv${slot}_action`, '').trim().toLowerCase();
        const readbackEntity = stateOf(`input_text.hpvc_pv${slot}_readback_entity`, '').trim().toLowerCase();
        const unit = stateOf(`input_select.hpvc_pv${slot}_limit_unit`, 'Watts').trim().toLowerCase();
        const fullPower = Number(stateOf(`input_number.hpvc_pv${slot}_full_limit`, '0'));
        const configured = method === 'Action/service'
            ? Boolean(action || readbackEntity)
            : Boolean(limitEntity);
        if (!configured) continue;
        configuredCount++;

        const liveEntity = method === 'Action/service' ? readbackEntity : limitEntity;
        if (!validEntityId(liveEntity)) {
            unavailable.push(`PV${slot} (no valid ${method === 'Action/service' ? 'readback' : 'limit'} entity)`);
            continue;
        }
        const live = numericState(liveEntity);
        if (live === null) {
            unavailable.push(`PV${slot} (${liveEntity} unavailable)`);
            continue;
        }
        if (!(Number.isFinite(fullPower) && fullPower > 0)) {
            unavailable.push(`PV${slot} (invalid full limit)`);
            continue;
        }

        const expectedRaw = unit === 'percent' ? 100 : fullPower;
        const toleranceRaw = unit === 'percent'
            ? Math.max(0.1, (deadbandW / fullPower) * 100)
            : deadbandW;
        if (live < expectedRaw - toleranceRaw) {
            notFull.push(`PV${slot} (${Math.round(live * 1000) / 1000}${unit === 'percent' ? '%' : ' W'} / full ${Math.round(expectedRaw * 1000) / 1000}${unit === 'percent' ? '%' : ' W'})`);
        }
    }
    return { configuredCount, unavailable, notFull };
}

const inverterVerification = configuredInverterVerification(states, stateOf);
const configuredInverterUnavailable = inverterVerification.unavailable.length > 0;
const configuredInverterNotFull = inverterVerification.notFull.length > 0;

