        `(status=${hpvcStatus || 'unknown'}, evaluation=${postDisableEvaluationComplete ? 'confirmed' : 'pending'}, ` +
        `runtime=${runtimeLockFresh ? 'busy' : 'idle'}, write=${pendingWriteActive ? 'pending' : 'idle'}, ` +
        `restore=${disableRestoreActive ? 'active' : 'idle'}, ` +
        `inverters=${configuredInverterUnavailable ? 'unavailable/unverifiable' : (configuredInverterNotFull ? 'not at full limit' : 'verified')}, ` +
        `hbc=${hbcManualRecoveryRequired ? 'manual recovery required' : (hbcOverrideActive ? 'restoring' : 'idle')}). ` +
        (configuredInverterUnavailable ? `Unverifiable inverter(s): ${inverterVerification.unavailable.join(', ')}. ` : '') +
        (configuredInverterNotFull ? `Inverter(s) not confirmed at full limit: ${inverterVerification.notFull.join(', ')}. ` : '') +
