}

node.status({
    fill:'yellow',
    shape:'ring',
    text: !postDisableEvaluationComplete
        ? 'waiting for engine evaluation'
        : configuredInverterUnavailable
            ? `waiting for ${inverterVerification.unavailable.join(', ')}`
            : configuredInverterNotFull
                ? `verifying full limit: ${inverterVerification.notFull.join(', ')}`
