                : hbcManualRecoveryRequired
                    ? 'HBC manual recovery required'
                    : hbcOverrideActive
                        ? 'restoring HBC override'
                        : 'confirming disabled state'
});

// Output 3 both drives a new normal HPVC evaluation and schedules another poll.
return [null, null, msg];

